def separate_paren_groups(paren_string: str) -> List[str]:
    result = []
    current_group = ''
    ignore_next = False
    for char in paren_string:
        if char == ' ':
            continue
        if char == '(':
            if current_group:
                result.append(current_group)
                current_group = ''
            current_group += char
        elif char == ')':
            if ignore_next:
                ignore_next = False
            else:
                current_group += char
                result.append(current_group)
                current_group = ''
        else:
            ignore_next = True
    if current_group:
        result.append(current_group)
    return result
```

