def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Initialize a 2D array to store the maximum sum of values collected on two paths
    dp = [[0] * (N + 1) for _ in range(N + 1)]

    # Iterate over the grid values and update the maximum sum on each path
    for x, y, value in grid_values:
        dp[x][y] = value
        if x > 0:
            dp[x][y] += dp[x - 1][y]
        if y > 0:
            dp[x][y] += dp[x][y - 1]

    # Return the maximum sum of values collected on the two paths
    return max(dp[N][-1], dp[-1][N])
```

