def cantor_numbering(N: int) -> str:
    """
    Determines the numerator and denominator of the N-th term in the Cantor table.
    """
    def find_period(n):
        a, b = 0, 1
        for k in range(n):
            a, b = b, a + b
        return a

    def find_start_index(n):
        a, b = 0, 1
        for k in range(n+1):
            a, b = b, a + b
        return a

    if N < 0:
        raise ValueError("N must be non-negative.")
    if N == 0:
        return "0/1"

    period = find_period(N)
    if period == N:
        return str(N) + "/1"

    start_index = find_start_index(N)
    num, denom = N - start_index, period - start_index
    return str(num) + "/" + str(denom)
```

