def verify_isbn(isbn):
    # Check if the input is a string
    if not isinstance(isbn, str):
        raise ValueError("Invalid ISBN number, expected a string.")

    # Check if the input has the correct format
    if len(isbn) != 17 or isbn[2] != "-" or isbn[6] != "-" or isbn[12] != "-" or isbn[17] not in "Xx":
        raise ValueError("Invalid ISBN number format.")

    # Convert the input to uppercase
    isbn = isbn.upper()

    # Calculate the checksum
    total = 0
    for i, char in enumerate(isbn[:-1], start=1):
        if i % 2 == 0:
            total += int(char)
        else:
            total += (int(char) * 3)

    # Check if the checksum is correct
    if isbn[-1] == "X" and total % 10 == 10 or isbn[-1] == str(total % 10):
        return "Right"
    else:
        # Calculate the corrected checksum
        total = (total // 10 + 1) * 10
        checksum = total - (int(isbn[0]) + int(isbn[2]) + int(isbn[4]) + int(isbn[4]) + int(isbn[7]) + int(isbn[8]) + int(isbn[10]) + int(isbn[12]) + int(isbn[14]) + int(isbn[16]))

        # Return the corrected ISBN number
        return isbn[:-1] + str(checksum)
